// BuzzFYL UI wired to the real core (src/core/, src/brain.ts). The UI owns look, copy, flow and
// the clock; the core owns the simulation, the brain lookups, the settings and the economy.
// Nothing here computes a neural response or a game outcome: it reads core state and records.
import { Brain } from "../../src/brain";
import { loadNotebook, restoreBuild, saveAttempt } from "../../src/core/campaign";
import { decisiveEvents, firstDivergence, frozenTwin, replay, runPair } from "../../src/core/compare";
import { ARENA, baselineLevels, buildCost, CTRL, GAME, POLICY_COST, POLICY_THRESHOLD, SUGAR_COST } from "../../src/core/config";
import { Sim } from "../../src/core/sim";
import { WAVES } from "../../src/core/waves";

const $=s=>document.querySelector(s);const clone=x=>JSON.parse(JSON.stringify(x));
const fly=`<svg viewBox="0 0 64 64" fill="none" aria-hidden="true"><ellipse cx="23" cy="23" rx="11" ry="17" transform="rotate(-35 23 23)" fill="#e2eef0" stroke="#352d24" stroke-width="2"/><ellipse cx="42" cy="23" rx="11" ry="17" transform="rotate(35 42 23)" fill="#e2eef0" stroke="#352d24" stroke-width="2"/><ellipse cx="32" cy="39" rx="10" ry="18" fill="#51483c" stroke="#352d24" stroke-width="2"/><path d="M23 35h18M23 43h18M25 51h14M23 35l-10 8M41 35l10 8" stroke="#c3b494" stroke-width="2"/><circle cx="32" cy="22" r="10" fill="#51483c"/><circle cx="26" cy="20" r="5" fill="#b64032"/><circle cx="38" cy="20" r="5" fill="#b64032"/></svg>`;
const icons={water:'<path d="M12 3C10 7 5 12 5 16a7 7 0 0014 0c0-4-5-9-7-13z"/>',sugar:'<path d="M6 8l6-4 6 4v9l-6 4-6-4zM6 8l6 4 6-4M12 12v9"/>',bitter:'<path d="M5 19C3 7 12 3 20 4c1 11-5 17-13 15M6 19L17 7"/>',threat:'<path d="M12 3L2 21h20L12 3zM12 9v5M12 17v1"/>',learn:'<path d="M5 8a8 8 0 0114 0M19 3v5h-5M19 16a8 8 0 01-14 0M5 21v-5h5"/>'};const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${icons[k]}</svg>`;

// ---- core-defined settings and economy ---------------------------------------------------
$('#app').innerHTML='<div class="shell"><p class="notice" style="padding:40px">Loading the measured brain export…</p></div>';
let brain;
try{brain=await Brain.load()}catch(e){$('#app').innerHTML=`<div class="shell"><p class="notice" style="padding:40px">Brain data unavailable: ${e.message}. Nothing is simulated without it.</p></div>`;throw e}
const WAVE='boss',wave=WAVES[WAVE];
const scales={bitter:brain.levels.bitterScale,loomGf:brain.levels.loomGfScale};
const sugars=Object.keys(SUGAR_COST).map(Number);
const base0=baselineLevels(scales);
// Scout / reset: the unmodified connectome, weakest sugar input, slow learning. Costs nothing.
const defaults={sugarHz:sugars[0],bitterLevel:base0.bitter,loomGfLevel:base0.loomGf,policy:{bitter:'conservative',loomGf:'conservative'}};
const query=new URLSearchParams(location.search);
const seed=Number(query.get('seed')??7);
const nSeeds=Math.max(...Object.values(brain.data.conditions).map(c=>c.runs.length));
const groupN=k=>brain.data.groups[k]?.root_ids.length??0;
const gname={bitter:'Bitter-cell outputs',loomGf:'Looming → Giant Fibre'};
const glow={bitter:'bitter-cell outputs',loomGf:'looming → Giant Fibre'};
// UI setting key -> BuildConfig field
const field={bitter:'bitterLevel',threat:'loomGfLevel'},grp={bitter:'bitter',threat:'loomGf'};
const level=(c,k)=>k==='sugar'?sugars.indexOf(c.sugarHz):c[field[k]];
const setLevel=(c,k,v)=>{if(k==='sugar')c.sugarHz=sugars[v];else c[field[k]]=v};
const levelText=(c,k)=>k==='sugar'?`${c.sugarHz} Hz`:`×${scales[grp[k]][c[field[k]]]}`;
const stateOf=c=>({bitterScale:scales.bitter[c.bitterLevel],loomGfScale:scales.loomGf[c.loomGfLevel]});
const measured=c=>brain.stateAvailable(stateOf(c),!!wave.needsWater);
const cost=()=>buildCost(st.config,defaults);
const budget=()=>wave.budget;
const canRelease=()=>cost()<=budget()&&measured(st.config)&&!st.live;
const brainLine=c=>`sugar ${c.sugarHz} Hz, bitter ×${scales.bitter[c.bitterLevel]}, threat ×${scales.loomGf[c.loomGfLevel]}`;

let saved=loadNotebook().filter(a=>a?.record?.wave===WAVE&&typeof a.record.metrics?.progress==='number');
let st={view:'picnic',selected:'bitter',config:clone(defaults),runs:saved,chosen:saved.at(-1)?.id,live:null,notice:'',speed:1,paused:false,replay:0,compare:null};
const meta={water:{title:'Water',desc:'Hydration is part of the picnic, not a setting.',detail:`Water taste cells (${groupN('water')} neurons) were run in the model. On their own they drive the feeding motor neuron MN9 only weakly, about 20 Hz, so drinking is slow. The ${CTRL.drinkMn9Hz} Hz drink threshold is ours. Droplets and soda spills appear at the picnic; there is no slider and no point cost.`,group:`Water taste cells · ${groupN('water')} neurons`},sugar:{title:'Sugar',desc:'Set how strongly food stimulates sugar-sensing cells.',detail:'Sugar is a sensory input: increasing this level sends stronger stimulation into sugar-sensing cells.',group:`LB3c sugar cells · ${groupN('sugar')} neurons`},bitter:{title:'Bitter',desc:'Set the starting strength of bitter-cell outputs.',detail:'Bitter cells signal a reason to reject food. This setting scales their outgoing connections, so weakening it can allow feeding despite a bitter taste. Safe meals weaken this group; poisoning strengthens it under the selected learning policy.',group:`Bitter-cell outgoing connections · ${groupN('bitter')} neurons`},threat:{title:'Threat',desc:'Set the starting strength of looming-to-escape connections.',detail:'An approaching shape supplies looming input. This setting scales the direct connections into Giant Fibre, the escape output. Stronger connections favor escape but can interrupt meals. Other threat pathways may still suppress feeding even when these direct connections are weak.',group:`LC4 / LPLC2 → Giant Fibre · ${groupN('looming')} → ${groupN('giant_fibre')} neurons`},learn:{title:'Learning',desc:'Decide how readily experience changes each connection group.',detail:`Responsive updates after ${POLICY_THRESHOLD.responsive} qualifying event. Conservative collects ${POLICY_THRESHOLD.conservative}. These are authored learning rules applied to real connectivity.`,group:'Bitter and threat connection groups'}};
const outcomes={survived:'Crossed and survived',not_crossed:'Alive, never reached the fruit',died_health:'Died from damage',died_energy:'Died: ran out of energy',died_thirst:'Died of thirst',running:'Ended early'};
const actions={idle:'Looking around',walking:'Walking (authored)',feeding:'Feeding (MN9)',drinking:'Drinking (MN9)',suppressed:'Feeding suppressed, no jump',refusing:'Refusing food (MN9 low)',escaping:'Escape jump (Giant Fibre)',laying:'Laying eggs on the fruit'};
const pct=x=>Math.round(x*100)+'%';const hz=x=>Math.round(x)+' Hz';
function toast(t){document.querySelector('.toast')?.remove();let e=document.createElement('div');e.className='toast';e.role='status';e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),4000)}
function nav(v){if(st.live&&st.view==='live'){st.paused=true}st.view=v;render()}
const number=a=>st.runs.findIndex(x=>x.id===a.id)+1;
const chosen=()=>st.runs.find(x=>x.id===st.chosen)||st.runs.at(-1);

// ---- brain monitor: schematic layout, measured rates only --------------------------------
const bar=(label,v,thr,max=220)=>`<div class="mrow"><span>${label}</span><div class="mbar"><i class="${thr!=null&&v>=thr?'hit':''}" style="width:${Math.min(100,v/max*100)}%"></i>${thr!=null?`<em style="left:${thr/max*100}%" title="threshold ${thr} Hz (authored)"></em>`:''}</div><b>${hz(v)}</b></div>`;
function monitor(){
  const sim=st.view==='live'?st.live:null,c=sim?sim.config:st.config,sel=st.view==='workbench'?st.selected:null;
  const bs=sim?sim.brainState:stateOf(c),d=sim?.lastDecision;
  const on=k=>d?(k==='sugar'&&d.stimulus.sugar>0)||(k==='bitter'&&d.stimulus.bitter>0)||(k==='water'&&d.stimulus.water>0)||(k==='threat'&&d.stimulus.looming>0):sel===k||(sel==='learn'&&(k==='bitter'||k==='threat'));
  const g=(k,name,val)=>`<div class="mg ${on(k)?'on':''}"><span>${name}</span><b>${val}</b></div>`;
  let h=g('sugar',`Sugar cells · LB3c · ${groupN('sugar')}`,d?`${d.stimulus.sugar} Hz in`:`${c.sugarHz} Hz in`)+g('bitter',`Bitter cells · ${groupN('bitter')} · outputs`,`×${bs.bitterScale}`)+g('water',`Water cells · ${groupN('water')}`,d?`${d.stimulus.water??0} Hz in`:'at droplets')+g('threat',`Looming LC4/LPLC2 · ${groupN('looming')} → GF`,`×${bs.loomGfScale}`);
  if(sim){
    h+=`<h4>Last lookup${d?` · ${d.t.toFixed(1)} s`:''}</h4>`;
    if(!d)h+='<p class="meta">No sensory input yet, so nothing has been looked up.</p>';
    else h+=bar('MN9 · feed',d.readouts.mn9,d.stimulus.water&&!d.stimulus.sugar?CTRL.drinkMn9Hz:CTRL.feedMn9Hz)+bar('Giant Fibre · jump',d.readouts.giant_fibre,CTRL.escapeGfHz)+bar('MDN · shown only',d.readouts.mdn,null)+`<p class="why">${d.reason}</p><p class="meta">bitter ${d.stimulus.bitter} Hz · looming ${d.stimulus.looming} Hz · ${d.conditionId} · model seed ${d.replicateSeed}</p>`;
  }else if(measured(c)){
    const m=s=>brain.mean(bs,s);
    h+=`<h4>Measured for this build</h4>`+bar(`Sugar ${c.sugarHz}`,m({sugar:c.sugarHz,bitter:0,looming:0}).mn9,CTRL.feedMn9Hz)+bar('Sugar + bitter',m({sugar:c.sugarHz,bitter:200,looming:0}).mn9,CTRL.feedMn9Hz)+bar('Water alone',m({sugar:0,bitter:0,looming:0,water:400}).mn9,CTRL.drinkMn9Hz)+bar('Looming 50',m({sugar:0,bitter:0,looming:50}).giant_fibre,CTRL.escapeGfHz)+bar('Looming 100',m({sugar:0,bitter:0,looming:100}).giant_fibre,CTRL.escapeGfHz)+`<p class="meta">Top three: MN9 (feed). Bottom two: Giant Fibre (jump). Tick = our threshold. Mean of ${nSeeds} model seed${nSeeds>1?'s':''} where exported.</p>`;
  }else h+='<p class="why">This brain state is not measured yet. It cannot be released.</p>';
  return h;
}
function updateMonitor(){const e=$('#monitor');if(e)e.innerHTML=monitor()}

function render(){let active=st.view==='live'||st.view==='results'||st.view==='compare'||st.view==='summary'?'picnic':st.view;$('#app').innerHTML=`<div class="shell"><header class="top"><div class="brand"><h1>BuzzFYL</h1><span>BUZZ FOR YOUR LIFE</span></div><nav class="nav" aria-label="Main navigation">${[['workbench','Workbench'],['picnic','Picnic'],['notebook','Notebook']].map(([v,n])=>`<button data-nav="${v}" class="${active===v?'active':''}" ${active===v?'aria-current="page"':''}>${n}</button>`).join('')}</nav><button class="help" data-nav="tutorial" aria-label="Open tutorial">?</button></header><div class="body"><aside class="sidebar"><section class="specimen"><span class="wave-stamp">Your field specimen</span><div class="fly-picture">${fly}</div><strong>Fly ${String(st.runs.length+1).padStart(2,'0')}</strong><small>${st.live?'Experiment in progress':'Ready for the picnic'}</small><p class="notice">${st.runs.length} recorded ${st.runs.length===1?'attempt':'attempts'}</p></section><section class="brain" aria-label="Brain monitor"><h3>Brain monitor</h3><div class="monitor" id="monitor">${monitor()}</div><small>Schematic layout, not anatomy. Rates are whole-brain model runs.</small></section></aside><main class="content view-${st.view}">${views[st.view]()}</main></div><footer class="footer"><span>${brain.label} · 200 ms reset-state trials · picnic seed ${seed}</span><span>Feeding and escape come from the model. Walking, jumps and the learning rule are authored.</span></footer></div>`;bind();if(st.view==='live')updateLive();}
function policy(group){const g=grp[group],p=st.config.policy[g];return `<div class="setting"><label>${group==='bitter'?'Bitter':'Threat'} learning</label><div class="seg">${['responsive','conservative'].map(x=>`<button data-policy="${group}:${x}" class="${p===x?'active':''}">${x[0].toUpperCase()+x.slice(1)}${POLICY_COST[x]?` · ${POLICY_COST[x]} pt`:''}</button>`).join('')}</div><p class="policy-detail">${p==='responsive'?'Responsive: one qualifying experience changes this connection group by one level. Adapts quickly, including after a misleading encounter.':'Conservative: waits for three qualifying experiences before changing this connection group by one level. Changes more slowly and retains its starting behavior longer.'}</p></div>`}
function meter(){const left=budget()-cost();return {left,html:Array.from({length:budget()},(_,i)=>`<i class="${i<left?'lit':''}"></i>`).join('')}}
const views={workbench(){let m=meta[st.selected],k=st.selected,mt=meter(),slider=['sugar','bitter','threat'].includes(k);return `<div class="loadout-budget"><span>Available points</span><div class="point-meter" role="meter" aria-label="Available upgrade points" aria-valuemin="0" aria-valuemax="${budget()}" aria-valuenow="${mt.left}">${mt.html}</div><strong class="budget">${mt.left} / ${budget()}</strong></div><div class="workbench"><section class="tree" aria-label="Capability branches"><div class="branch"><div class="branch-title">Feeding</div><div class="nodes">${node('sugar')}${node('bitter')}${node('water')}</div></div><div class="branch"><div class="branch-title">Escape</div><div class="nodes">${node('threat')}${node('learn')}</div></div><p class="tree-note">Build your loadout!</p></section><section class="inspector"><h3>${m.title}</h3><p>${m.desc}</p>${slider?`<div class="setting"><label for="level">Starting level <span class="readout">${levelText(st.config,k)}</span></label><input id="level" type="range" min="0" max="${k==='sugar'?sugars.length-1:scales[grp[k]].length-1}" step="1" value="${level(st.config,k)}" aria-label="${m.title}" aria-valuetext="${levelText(st.config,k)}"><div class="range-ends"><span>Lower</span><span>Higher</span></div></div>`:''}${k==='bitter'||k==='learn'?policy('bitter'):''}${k==='threat'||k==='learn'?policy('threat'):''}<p class="notice">${m.detail}</p><button data-act="info">Connection details</button></section></div><div class="bottom-actions"><button data-act="reset">Reset settings</button>${st.live?'<button data-act="resume">Resume attempt</button>':''}<span class="notice" id="allocated">${allocated()}</span><button class="primary" data-act="release" ${canRelease()?'':'disabled'}>Release Fly</button></div>`},picnic(){return `<div class="garden"><div class="arrival-fly" aria-hidden="true">${fly}</div><div class="garden-title"><h2>One small step for fly. One giant buzz for flykind.</h2><p>Mack's Pest Control is on the way. Can you build a brain that gets you across the picnic before he gets here?</p><div class="arrival-actions"><button class="primary" data-nav="workbench">Build your fly</button><button data-act="scout" ${st.live?'disabled':''}>Scout: basic model</button></div><button class="quiet" data-nav="tutorial">First time here?</button></div><button class="notebook-hotspot" data-act="open-book"><span>Open notebook</span><small>${st.runs.length} recorded attempts</small></button></div><div class="bottom-actions">${st.live?'<button data-act="resume">Resume encounter</button><button data-act="finish">End attempt</button>':''}</div>`},live(){const s=st.live;if(!s)return empty();const fr=s.wave.fruit;return `<div class="screen-head"><div><h2>Mack’s Pest Control</h2><p id="phase"></p></div><div class="toolbar"><button data-act="pause" id="pause">${st.paused?'Play':'Pause'}</button>${[.5,1,2,4].map(v=>`<button data-speed="${v}" class="${st.speed===v?'active':''}">${v}×</button>`).join('')}</div></div><div class="live-stats"><span>Energy <b id="energy"></b><div class="bar"><i id="energy-bar"></i></div></span><span>Water <b id="water"></b><div class="bar"><i id="water-bar"></i></div></span><span>Health <b id="health"></b></span><span>Servings <b id="food"></b></span><span>Eggs <b id="eggs"></b></span><span id="clock"></span></div><div class="arena world" id="arena"><div class="ent fruit-zone" style="left:${fr.x/ARENA.w*100}%;top:${fr.y/ARENA.h*100}%;width:${fr.r*2/ARENA.w*100}%;height:${fr.r*2/ARENA.h*100}%" title="Fruit: the far side of the picnic">Fruit</div>${(s.wave.candles??[]).map(c=>`<div class="ent candle" style="left:${c.x/ARENA.w*100}%;top:${c.y/ARENA.h*100}%" title="Citronella candle: food beside it is coated"></div>`).join('')}<div id="ents"></div><div class="fly-token ent" id="fly">${fly}</div><div class="arena-label" id="action"></div></div><div class="event-line" id="event" aria-live="polite"></div><div class="event-line legend notice">S sugar food · B bitter-tasting food (safe, citronella-coated or poisoned: the fly tastes the same thing) · W water · So soda · dashed grey = passing shadow · red = swat · pale = Mack’s fog</div><div class="bottom-actions"><span id="levels" class="notice"></span><button data-act="finish">End & review</button></div>`},results(){let a=chosen();if(!a)return empty();let r=a.record,ev=decisiveEvents(r),learned=r.events.filter(e=>e.learning?.applied);return `<div class="screen-head"><div><h2>${r.result==='survived'?'A picnic survived.':'A useful experiment.'}</h2><p>Attempt ${number(a)} · Mack’s Pest Control · ${outcomes[r.result]} · ${mode(r)}</p></div><button data-nav="notebook">Save & open notebook</button></div><div class="results-grid"><section><h3>Field results</h3>${stats(r)}</section><section><h3>What changed?</h3><p class="notice">Started: ${brainLine(r.config)}.<br>Ended: bitter ×${r.finalState.bitterScale}, threat ×${r.finalState.loomGfScale}.</p><ul class="events">${learned.map(e=>`<li>${learnText(e)}</li>`).join('')||'<li>No weight changed in this attempt.</li>'}</ul><p class="notice">Authored learning applied to real connectivity. Each level’s effect is the measured model response.</p></section></div><div class="replay"><h3>Replay the evidence</h3>${ev.length?`<input id="replay" aria-label="Decisive events" type="range" min="0" max="${ev.length-1}" value="${Math.min(st.replay,ev.length-1)}"><div id="replay-detail"></div>`:'<p class="notice">No weight updates, damage or escapes were recorded in this attempt.</p>'}</div><div class="bottom-actions"><button data-act="restore">Revise starting brain</button><button data-act="compare">Compare Frozen Learning</button>${r.result==='survived'?`<button class="primary" data-act="advance">Final summary</button>`:'<button class="primary" data-act="retry">Retry boss encounter</button>'}</div>`},notebook(){let a=chosen(),r=a?.record;return `<div class="screen-head"><div><h2>Field Notebook</h2></div><div class="toolbar"><button data-act="export" ${!st.runs.length?'disabled':''}>Export records</button></div></div>${!a?`<div class="empty"><h3>A fresh page.</h3><p>Release your first fly to record its settings, discoveries, and results.</p><button class="primary" data-nav="workbench">Open workbench</button></div>`:`<div class="book"><section class="book-page"><h3>Recorded attempts</h3>${[...st.runs].reverse().map(x=>`<button class="run-entry ${x.id===a.id?'active':''}" data-run="${x.id}"><strong>Attempt ${number(x)} · Boss encounter</strong><span>Mack’s Pest Control · ${x.record.result==='survived'?'Survived':pct(x.record.metrics.progress)+' across'} · ${mode(x.record)}</span></button>`).join('')}</section><section class="book-page"><h3>Attempt ${number(a)}</h3>${stats(r)}<p class="notice">Starting brain: ${brainLine(r.config)}.<br>Learning: bitter ${r.config.policy.bitter}, threat ${r.config.policy.loomGf}.<br>Final brain: bitter ×${r.finalState.bitterScale}, threat ×${r.finalState.loomGfScale}.</p><ul class="events">${r.events.filter(e=>e.learning?.applied).map(e=>`<li>${learnText(e)}</li>`).join('')||'<li>No weight changed.</li>'}</ul><p class="notice">Picnic seed ${r.worldSeed} · ${r.version.core} · controller ${r.version.controller} · rule ${r.version.learningRule} · brain export ${r.version.brainExportedAt??'unknown'} · ${r.decisions.length} lookups and ${r.events.length} events in the exported log.</p><div class="bottom-actions"><button data-act="restore">Restore start</button><button data-act="restore-final">Use adapted brain</button><button data-act="review">Replay</button></div></section></div>`}`},compare(){let c=st.compare;if(!c)return empty();const d=c.div;return `<div class="screen-head"><div><h2>Did learning help?</h2><p>Same starting brain, picnic seed and body controller. One difference. ${verdict(c)}</p></div><button data-nav="results">Back to replay</button></div><div class="compare">${[c.adaptive,c.frozen].map((r,i)=>`<section><h3>${i?'Frozen connections':'Adaptive connections'}</h3><p>${i?'Starting weights stay fixed.':'Experience can change the weights.'}</p>${stats(r)}<p>Final bitter: <b>×${r.finalState.bitterScale}</b><br>Final threat: <b>×${r.finalState.loomGfScale}</b></p><ul class="events">${r.events.filter(e=>e.learning?.applied).map(e=>`<li>${learnText(e)}</li>`).join('')||'<li>Weights remained at their starting levels.</li>'}</ul></section>`).join('')}</div><div class="pad"><p class="notice">${d?`The two flies first differ at ${d.t.toFixed(1)} s. Adaptive${at(d.a)}: ${d.a?.reason??'no lookup'}. Frozen${at(d.b)}: ${d.b?.reason??'no lookup'}. After that they can meet different inputs.`:'The two flies made the same decisions throughout.'}</p><p class="notice">Both runs are full encounters looked up from the same measured model export. Learning can help or hurt.</p><button class="primary" data-nav="workbench">Try another configuration</button></div>`},tutorial(){return `<div class="screen-head"><h2>Welcome to BuzzFYL.</h2><button data-nav="workbench">Skip tutorial</button></div><div class="tutorial">${[['Get across the family picnic.','One encounter at the Bennett family picnic. Reach the fruit on the far side and stay alive while Mack’s Pest Control fogs it. Eggs laid on the fruit are a bonus. Your fly acts on its own. You shape the starting brain.'],['Build within your budget.','Select a capability in the workbench. Adjust its starting level and choose how readily it changes through experience. Moving a weight one level costs a point. The brain monitor shows what the model measured for your build.'],['Let the fly discover the picnic.','You do not steer. Watch it encounter food, water and approaching threats. Pause, slow down, or fast-forward. The map stays the same when you retry.'],['Experience changes the next decision.','Safe bitter meals can weaken bitter responses. Poisoning can strengthen them. Harmless shadows can lower threat sensitivity and hits raise it. These are authored learning rules applied to real connection groups.'],['Inspect. Adjust. Try again.','Replay the decisive events. Compare adaptive versus frozen learning, then restore a configuration from your field notebook.'],['What is real here.','Every feed, drink and jump decision is a lookup of a whole-fly-brain model run (FlyWire connectome) at the fly’s current weights. Walking, jump direction, energy, poison and the learning rule are game mechanics. Citronella is a stand-in read through bitter taste cells.']].map(([a,b],i)=>`<section><div class="num">${i+1} / 6</div><h2>${a}</h2><p>${b}</p></section>`).join('')}<button class="primary" data-nav="workbench">Prepare your first fly</button></div>`},summary(){const a=chosen(),r=a?.record;return `<div class="summary"><div class="fly-picture">${fly}</div><h2>You outlasted pest control.</h2><p>Your field notebook holds the story of how your fly changed.</p>${r?`<p>Began with ${brainLine(r.config)}.<br>Became bitter ×${r.finalState.bitterScale}, threat ×${r.finalState.loomGfScale} after ${r.metrics.adaptations} weight ${r.metrics.adaptations===1?'update':'updates'}.<br>Reached the fruit at ${r.metrics.reachedFruitAt?.toFixed(0)} s, laid ${r.metrics.eggsLaid} ${r.metrics.eggsLaid===1?'egg':'eggs'}, took ${r.metrics.damageTaken} damage.</p>`:''}<p>${st.runs.length} boss attempts recorded</p><button class="primary" data-nav="notebook">Open the notebook</button> <button data-act="new">Back to the picnic</button><p class="notice">Authored learning applied to real connectivity. Every lookup is a fresh 200 ms trial.</p></div>`}};
const at=d=>d?` (bitter ×${d.state.bitterScale}, threat ×${d.state.loomGfScale})`:'';
function allocated(){return measured(st.config)?`${cost()} points allocated`:'This brain state is not measured yet'}
function mode(r){return r.config.policy.bitter==='frozen'&&r.config.policy.loomGf==='frozen'?'Frozen Learning':'Adaptive Learning'}
function node(k){return `<button class="node ${st.selected===k?'selected':''}" data-node="${k}">${icon(k)}${meta[k].title}${k==='water'?'<small>Measured, weak</small>':''}</button>`}function empty(){return '<div class="empty"><h2>No attempt yet.</h2><button data-nav="workbench">Open workbench</button></div>'}
function stats(r){const m=r.metrics;return `<table class="stats-table">${[['Encounter progress',pct(m.progress)],['Outcome',outcomes[r.result]],['Servings completed',m.servingsCompleted],['Drinks',m.drinks],['Eggs laid (bonus)',m.eggsLaid],['Damage taken',m.damageTaken],['Escape jumps',`${m.jumps} (${m.jumpsOnHarmless} at harmless shadows)`],['Attacks that missed after a jump',m.attacksEscaped],['Meals interrupted by a jump',m.mealsInterruptedByJump],['Weight updates',m.adaptations]].map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</table>`}
function learnText(e){const l=e.learning;return `${e.t.toFixed(1)} s · ${e.feedback}: ${glow[l.group]} ×${l.scaleBefore} → ×${l.scaleAfter}`}
function verdict(c){const a=c.adaptive,f=c.frozen,ok=r=>r.result==='survived';if(ok(a)&&!ok(f))return 'Here learning helped.';if(!ok(a)&&ok(f))return 'Here learning hurt.';return `Same outcome either way; eggs ${a.metrics.eggsLaid} adaptive, ${f.metrics.eggsLaid} frozen.`}

// ---- commands onto the core --------------------------------------------------------------
function release(config){st.notice='';st.live=new Sim(brain,{wave:WAVE,seed,config:clone(config),onEvent:e=>{if(e.outcome==='serving_refused'&&!e.learning)return;const l=e.learning;st.notice=`${e.t.toFixed(1)} s · ${e.feedback}${l?` · ${gname[l.group]}: ${l.applied?`×${l.scaleBefore} → ×${l.scaleAfter}`:l.note}`:''}`}});st.paused=false;st.speed=1;acc=0;nav('live')}
function finish(){let s=st.live;if(!s)return;const a=saveAttempt(s.record());st.runs.push(a);st.live=null;st.chosen=a.id;st.replay=0;st.view='results';render()}
const px=(x,y)=>`left:${x/ARENA.w*100}%;top:${y/ARENA.h*100}%`;
const foodLook={clean:['','S','Sugar food'],safe_bitter:['bitter','B','Bitter-tasting food'],poison_bitter:['bitter','B','Bitter-tasting food'],citronella:['bitter','B','Bitter-tasting food beside a citronella candle'],water:['water','W','Water droplet'],soda:['soda','So','Spilled soda: sugar and water']};
function updateLive(){let s=st.live;if(!s||!$('#fly'))return;const f=s.fly,m=s.metrics;$('#energy').textContent=Math.round(f.energy);$('#energy-bar').style.width=f.energy/GAME.maxEnergy*100+'%';$('#water').textContent=Math.round(f.hydration);$('#water-bar').style.width=f.hydration/GAME.maxHydration*100+'%';$('#health').textContent=Math.round(f.health)+'/'+GAME.maxHealth;$('#food').textContent=m.servingsCompleted;$('#eggs').textContent=m.eggsLaid;$('#clock').textContent=Math.floor(s.t)+' / '+s.wave.duration+' s';$('#phase').textContent=`${s.phase} · ${mode(s)}`;$('#action').textContent=actions[f.action];$('#event').textContent=st.notice||'The fly is exploring. No adaptation recorded yet.';
  $('#levels').textContent=['bitter','loomGf'].map(g=>{const x=s.groups[g],e=x.evidence;return `${g==='bitter'?'Bitter':'Threat'} ×${scales[g][x.startLevel]} → ×${scales[g][x.level]}${e.direction?` (pending ${e.count}/${x.threshold} to ${e.direction})`:''}`}).join(' · ');
  const el=$('#fly');el.style.left=f.x/ARENA.w*100+'%';el.style.top=f.y/ARENA.h*100+'%';el.style.transform=`translate(-50%,-50%) rotate(${f.heading*180/Math.PI+90}deg)`;el.className='fly-token ent '+f.action;
  $('#ents').innerHTML=s.servings.filter(x=>x.status==='available').map(x=>{const[c,t,title]=foodLook[x.kind];return `<div class="ent food ${c} ${x.refusedUntil>s.t?'dim':''}" style="${px(x.x,x.y)}" title="${title}">${t}${x.progress>0?`<u style="width:${x.progress*100}%"></u>`:''}</div>`}).join('')+s.threats.filter(t=>t.status==='active').map(t=>`<div class="ent threat show ${t.kind}" style="${px(t.x,t.y)};width:${CTRL.hitRadius*2/ARENA.w*100}%;height:${CTRL.hitRadius*2/ARENA.h*100}%"><span>${t.kind==='fog'?'Mack’s fog':t.kind==='swat'?'Swat':'Shadow'}</span></div>`).join('');
  if(s.lastDecision?.id!==shown){shown=s.lastDecision?.id;updateMonitor()}}
let shown=null;
function replayDetail(){let a=chosen(),box=$('#replay-detail');if(!a||!box)return;const r=a.record,ev=decisiveEvents(r),e=ev[Math.min(st.replay,ev.length-1)];if(!e)return;const{decision:d}=replay(r,e),l=e.learning;box.innerHTML=`<p><b>Event ${Math.min(st.replay,ev.length-1)+1} of ${ev.length} · ${e.t.toFixed(1)} s · ${e.outcome.replaceAll('_',' ')}</b></p><ol class="events">${d?`<li>Sensory input: sugar ${d.stimulus.sugar} Hz, bitter ${d.stimulus.bitter} Hz, looming ${d.stimulus.looming} Hz${d.stimulus.water?`, water ${d.stimulus.water} Hz`:''}. Condition ${d.conditionId}, model seed ${d.replicateSeed}.</li><li>Measured output: MN9 ${hz(d.readouts.mn9)}, Giant Fibre ${hz(d.readouts.giant_fibre)}, MDN ${hz(d.readouts.mdn)}.</li><li>Controller action: ${d.action}. ${d.reason}.</li>`:'<li>No lookup is linked to this event.</li>'}<li>Resolved feedback: ${e.feedback}.</li><li>Weight update: ${l?`${glow[l.group]}, evidence ${l.evidenceBefore.count} → ${l.note}. ${l.applied?`Weight ×${l.scaleBefore} → ×${l.scaleAfter}; the next decision uses it.`:`Weight stays ×${l.scaleBefore}.`}`:'none. This event gives no evidence.'}</li></ol>`}
function bind(){document.querySelectorAll('[data-nav]').forEach(e=>e.onclick=()=>nav(e.dataset.nav));document.querySelectorAll('[data-node]').forEach(e=>e.onclick=()=>{st.selected=e.dataset.node;render()});$('#level')?.addEventListener('input',e=>{setLevel(st.config,st.selected,+e.target.value);const t=levelText(st.config,st.selected),mt=meter();$('.readout').textContent=t;e.target.setAttribute('aria-valuetext',t);$('.budget').textContent=mt.left+' / '+budget();$('.point-meter').setAttribute('aria-valuenow',mt.left);document.querySelectorAll('.point-meter i').forEach((segment,i)=>segment.classList.toggle('lit',i<mt.left));document.querySelector('[data-act=release]').disabled=!canRelease();$('#allocated').textContent=allocated();updateMonitor()});document.querySelectorAll('[data-policy]').forEach(e=>e.onclick=()=>{let[g,p]=e.dataset.policy.split(':');st.config.policy[grp[g]]=p;render()});document.querySelectorAll('[data-speed]').forEach(e=>e.onclick=()=>{st.speed=+e.dataset.speed;render()});document.querySelectorAll('[data-run]').forEach(e=>e.onclick=()=>{st.chosen=e.dataset.run;render()});$('#replay')?.addEventListener('input',e=>{st.replay=+e.target.value;replayDetail()});document.querySelectorAll('[data-act]').forEach(e=>e.onclick=()=>act(e.dataset.act));replayDetail()}
function act(a){let r=chosen();if(a==='scout'){if(st.live)return;release(defaults)}if(a==='release'){if(!canRelease())return;release(st.config)}if(a==='pause'){st.paused=!st.paused;render()}if(a==='resume'){st.paused=false;nav('live')}if(a==='finish')finish();if(a==='reset'){st.config=clone(defaults);render()}if(a==='info')toast(meta[st.selected].group+'. FlyWire v783 neuron IDs are in the export; measured rates are on the brain monitor.');if(a==='restore'||a==='restore-final'){if(!r)return;st.config=restoreBuild(r,a==='restore'?'start':'final');nav('workbench');toast(a==='restore'?'Starting configuration restored.':cost()>budget()?'Adapted configuration restored. It is over budget: adjust before release.':'Adapted configuration restored.')}if(a==='review'){st.replay=0;nav('results')}if(a==='retry'){if(!r||st.live)return;st.config=restoreBuild(r,'start');release(st.config)}if(a==='advance'){nav('summary')}if(a==='compare'){if(!r)return;const cfg=r.record.config,[adaptive,frozen]=runPair(brain,WAVE,r.record.worldSeed,cfg,frozenTwin(cfg));st.compare={adaptive,frozen,div:firstDivergence(adaptive,frozen)};nav('compare')}if(a==='export'){let b=new Blob([JSON.stringify(st.runs,null,2)],{type:'application/json'}),u=URL.createObjectURL(b),l=document.createElement('a');l.href=u;l.download='buzzfyl-notebook.json';l.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}if(a==='new'){nav('picnic')}if(a==='open-book'){st.bookReturn='picnic';nav('notebook')}}
// The UI owns the clock. Speed and pause change how fast fixed core steps are consumed, never the result.
let acc=0,prev=performance.now();
function frame(now){const dt=Math.min(.1,(now-prev)/1000);prev=now;if(st.view==='live'&&st.live&&!st.paused){acc+=dt*st.speed;const n=Math.floor(acc/CTRL.dt);if(n>0){acc-=n*CTRL.dt;st.live.step(n*CTRL.dt);updateLive();if(st.live.done)finish()}}requestAnimationFrame(frame)}
// Dev aid: ?view=workbench|notebook|tutorial|live|results|compare (&t=seconds for live) opens a screen directly.
{const v=query.get('view');if(v==='live'||v==='results'||v==='compare'){release(st.config);st.live.step(v==='live'?Number(query.get('t')??20):999);if(v==='live')st.paused=true;else{finish();if(v==='compare')act('compare')}}else if(views[v])st.view=v}
render();requestAnimationFrame(frame);

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&st.view==='notebook'){nav(st.bookReturn||'picnic')}else if(e.key==='Escape'&&st.view==='live'){st.paused=!st.paused;render()}});
